# Caller label for the shared model-group lookup, not a required group id.
_ORCHESTRATOR_COMPONENT_NAME = "orchestrator"

V2_RESPONSES_ARTIFACT_PATH = f"{MANTLE_SNAPSHOT_DIR}/{RESPONSES_FILENAME}"
V2_PROJECT_MEMORY_ARTIFACT_PATH = f"{MANTLE_SNAPSHOT_DIR}/memory.yml"
V2_AGENT_ARTIFACT_PATH = f"{MANTLE_SNAPSHOT_DIR}/{MANTLE_AGENT_FILE}"


class ModelBootstrap(BaseModel):
    """Immutable bootstrap bundle for one loaded model.

    Built once at model load from the packaged snapshot; shared across all
    turns served by the same processor instance.
    """

    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)

    llm: dict[str, Any]
    """Resolved orchestrator client config from the packaged group id and live
    ``model_groups``.
    """

    tool_funcs: dict[str, dict[str, Callable[..., Any]]] = Field(default_factory=dict)
    """Skill-scoped local tool registry: ``{skill_id: {tool_name: func}}``.

    Populated at model-load time by importing each ``skills/<id>/tools.py``
    from bundled default skills and the packaged archive snapshot (snapshot
    overrides defaults on duplicate tool names).  Two skills may define tools
    with the same name without conflict because lookup is always scoped to the
    active skill ID.  Empty for skills that do not declare any builder-defined
    LLM tools. MCP tool allowlists are stored separately in ``mcp_tool_allowlist``.
    """

    mcp_tool_allowlist: dict[str, tuple[MCPToolReference, ...]] = Field(
        default_factory=dict
    )
    """Skill-scoped MCP allowlist: ``{skill_id: (server_id, tool_name)...}``.

    Parsed from ``import_tools`` at model load. Schemas and connections are
    not stored here; they live on the processor-owned MCP runtime.
    """

    mcp_servers: Optional[MCPServersSettings] = None
    """Validated ``mcp_servers`` block from ``integrations.yml``, if any."""

    skill_catalog: SkillCatalog = Field(default_factory=SkillCatalog)
    """Skill catalog loaded from ``<snapshot>/skills/`` merged with built-in
    default skills.  Empty catalog when no skills are packaged.
    """

    response_registry: ResponseRegistry = Field(default_factory=ResponseRegistry)
    """Response registry loaded from ``<snapshot>/responses.yml``.
    Empty registry when the snapshot does not include a top-level responses file.
    """

    project_memory: ProjectMemorySchema = Field(default_factory=ProjectMemorySchema)
    """Project-wide memory schema from ``<snapshot>/memory.yml``.

    Shared across all skills; defines cross-skill namespaced slots prefixed
    with ``project.``.  Empty schema when the snapshot has no such file.
    """

    agent: AgentSpec
    """Agent identity and orchestrator settings parsed from the packaged
    ``agent.yml``. Required: the orchestrator group id lives here."""

    session: SessionSpec = Field(default_factory=SessionSpec)
    """Conversation-session settings (expiration, start-after-expiry) parsed from
    the ``session_config`` block of the packaged ``agent.yml``.  Defaults when
    the snapshot carries no session block.  Read by
    ``MantleMessageProcessor.session_config`` (ENG-2875)."""

    references_index: InformationRetrieval | None = None
    """Local FAISS index over the packaged ``references/`` files, or ``None`` when
    the project ships no reference files. Built at train time
    (``references_index.build_references_index``) and loaded here at model load;
    the ``search_knowledge`` tool queries it as a knowledge source."""

    skills_index: InformationRetrieval | None = None
    """Local FAISS index over startable skills, or ``None`` when
    retrieval cannot filter. Built at train time
    (``skills_index.build_skills_index``) and loaded here at model load."""

    hooks: HookRegistry = Field(default_factory=HookRegistry.empty)
    """Project-wide hook registry loaded from ``hooks.py`` and ``hooks/**/*.py``.

    Populated at model-load time. Empty when the project defines no hooks.
    """

    privacy: dict[str, Any] | None = None
    """Optional ``privacy`` block from packaged ``agent.yml`` (Mantle PII pipeline)."""


def _load_failure_cause(error: BaseException) -> str:
    """Return a one-line cause that does not quote file contents.

    Parser errors include the offending line and, for a duplicate key, both
    values. A line from ``integrations.yml`` can hold a secret, so the logged
    cause keeps the problem statement and drops quoted values and snippets.
    """
    problem = _yaml_problem(error)
    message = problem or _first_line(str(error)) or type(error).__name__
    marker = " with value "
    if "found duplicate key " in message and marker in message:
        return message.split(marker, 1)[0].strip()
    return message


def _yaml_problem(error: BaseException) -> str:
    problem = getattr(error, "problem", None)
    if isinstance(problem, str) and problem.strip():
        return _first_line(problem)
    underlying = getattr(error, "underlying_yaml_exception", None)
    if isinstance(underlying, BaseException):
        return _yaml_problem(underlying)
    return ""


def _first_line(message: str) -> str:
    return next((line.strip() for line in message.splitlines() if line.strip()), "")


def resolve_static_data_from_archive(
    model_archive_path: Union[str, Path],
    engine_version: str,
    project_root: Union[str, Path, None] = None,
) -> ModelBootstrap:
    """Resolve static inputs from the packaged snapshot and project.

    Only valid for Mantle models. Raises ``ValueError`` when called for any other
    engine version (a programming error — the snapshot only exists for v2), and
    ``ValidationError`` when a v2 snapshot is missing required artifacts.
    ``InvalidConfigException`` from the live integrations file is raised unchanged
    so ``rasa run`` and ``rasa inspect`` show the config message.

    The archive is extracted once to a temporary directory; all artifact reads
    and the skill catalog load are performed against that directory before
    it is cleaned up.
    """
    if engine_version != MANTLE_ENGINE_VERSION:
        raise ValueError(
            "resolve_static_data_from_archive is only valid for Mantle models, "
            f"but was called with engine_version={engine_version!r}."
        )

    archive_path = Path(model_archive_path)

    try:
        with windows_safe_temporary_directory() as tmp_dir:
            tmp_path = Path(tmp_dir)
            # Intentional private-API use: no public extraction helper exists.
            LocalModelStorage._extract_archive_to_directory(archive_path, tmp_path)
            return _resolve_from_extracted(tmp_path, project_root)
    except (ValidationError, InvalidConfigException):
        raise
    except Exception as error:
        raise ValidationError(
            code="mantle.model_archive.bootstrap.config_load_failed",
            event_info=(
                "Failed to load Mantle model metadata from model archive "
                f"'{archive_path}'."
            ),
            error_type=type(error).__name__,
            error=_load_failure_cause(error),
        ) from error


def _resolve_from_extracted(
    tmp_path: Path,
    project_root: Union[str, Path, None],
) -> ModelBootstrap:
    """Build :class:`ModelBootstrap` from an already-extracted archive directory.

    Separated from :func:`resolve_static_data_from_archive` so that tests can
    call it directly with a pre-populated temp directory.
    """
    # Packaged snapshot root — reused across the artifact reads below.
    snapshot_root = tmp_path / MANTLE_SNAPSHOT_DIR

    # The group id is packaged; model definitions stay on the live integrations file.
    config_data = _read_agent_yaml_from_archive(tmp_path)
    agent = agent_spec_from_config(config_data)
    privacy = extract_privacy_mapping(config_data)
    session = session_spec_from_config(config_data)
    llm_config = resolve_integration_llm_config(agent, project_root)

    # --- skill catalog ---
    from rasa.mantle.skills.catalog import (
        load_default_skill_catalog,
        load_skill_catalog,
    )

    default_skill_catalog = load_default_skill_catalog()
    skill_catalog = load_skill_catalog(
        snapshot_root,
        defaults=default_skill_catalog,
    )

    # --- tool funcs (skill-scoped) ---
    from rasa.mantle.tools.loader import load_tools_for_skill_catalog

    snapshot_skills_root = snapshot_root / "skills"
    defaults_skills_root = Path(__file__).parent.parent / "default_skills"
    tool_funcs: dict[str, dict[str, Callable[..., Any]]] = {}
    if skill_catalog.skills:
        # Not gated on ``snapshot_skills_root.is_dir()``: a project may ship only
        # a shared root ``tools/`` and no ``skills/`` dir. The loader tolerates a
        # missing skills dir (skill-local discovery returns empty) and still
        # discovers the shared tools that each skill declares.
        tool_funcs = load_tools_for_skill_catalog(
            skill_catalog,
            snapshot_skills_root,
            defaults_skills_root=defaults_skills_root,
        )

    mcp_tool_allowlist = parse_mcp_imports(skill_catalog, tool_funcs)
    mcp_servers = (
        load_integration_mcp_servers(project_root)
        if project_root is not None
        else load_integration_mcp_servers(Path.cwd())
    )

    # --- response registry (default skills → project skills → top-level) ---
    # Priority (highest wins): top-level snapshot/responses.yml overrides project
    # skill responses, which override default skill responses.
    response_registry = load_response_registry(
        snapshot_skills_root=snapshot_skills_root,
        top_level_path=tmp_path / V2_RESPONSES_ARTIFACT_PATH,
    )

    # --- project memory schema ---
    project_memory = ProjectMemorySchema.from_yaml(
        tmp_path / V2_PROJECT_MEMORY_ARTIFACT_PATH
    )
    # Memory-declaration validation runs at *training* time (see
    # rasa.mantle.validation.validate_project, called from package_model_archive),
    # not here at model load.

    # --- local references FAISS index (file-based knowledge tier) ---
    # Deferred import avoids a bootstrap <-> references_index module cycle
    # (references_index imports resolve_integration_model_groups from here).
    from rasa.mantle.model_archive.references_index import load_references_index

    # Resolve the embeddings model groups from the packaged snapshot's
    # integrations.yml (not project_root/cwd): the index was built at train time
    # against that copy, so query-time embeddings must resolve from the same
    # source or the query vectors will not match the indexed vectors.
    snapshot_model_groups = resolve_integration_model_groups(snapshot_root)
    references_index = load_references_index(
        snapshot_root,
        agent,
        snapshot_model_groups,
    )

    # Deferred import avoids a bootstrap <-> skills_index module cycle
    # (skills_index imports resolve_integration_model_groups from here).
    from rasa.mantle.model_archive.skills_index import load_skills_index

    skills_index = load_skills_index(
        snapshot_root,
        agent,
        snapshot_model_groups,
        skill_catalog,
    )

    from rasa.mantle.hooks.loader import load_hooks

    hooks = load_hooks(snapshot_root, evict_lib=False)

    return ModelBootstrap(
        llm=dict(llm_config),
        tool_funcs=tool_funcs,
        mcp_tool_allowlist=mcp_tool_allowlist,
        mcp_servers=mcp_servers,
        skill_catalog=skill_catalog,
        response_registry=response_registry,
        project_memory=project_memory,
        agent=agent,
        session=session,
        references_index=references_index,
        skills_index=skills_index,
        hooks=hooks,
        privacy=privacy,
    )


def load_default_system_responses() -> ResponseRegistry:
    """Load the packaged system default responses.

    These are engine-level default messages bundled at
    ``rasa/mantle/default_skills/default_responses.yml``. They form the
    lowest-priority layer of the response registry so any user-defined
    response with the same name overrides them. This module lives in the
    ``model_archive`` subpackage, so the bundled file sits one level up under
    ``rasa/mantle/default_skills``.
    """
    path = Path(__file__).parent.parent / "default_skills" / "default_responses.yml"
    return ResponseRegistry.from_yaml(path)


def load_bundled_response_registry() -> ResponseRegistry:
    """Load packaged system and default-skill responses (no project files).

    Used as the base layer before merging project ``skills/*/responses.yml``
    and top-level ``responses.yml`` at model load or during validation.
    """
    registry = load_default_system_responses()

    default_skills_dir = Path(__file__).parent.parent / "default_skills"
    if default_skills_dir.is_dir():
        for skill_dir in sorted(default_skills_dir.iterdir()):
            if not skill_dir.is_dir() or skill_dir.name.startswith("_"):
                continue
            skill_responses = skill_dir / RESPONSES_FILENAME
            if skill_responses.is_file():
                registry = ResponseRegistry.from_yaml(skill_responses).merge(registry)

    return registry


def load_response_registry(
    snapshot_skills_root: Path,
    top_level_path: Path,
) -> ResponseRegistry:
    """Build a merged :class:`ResponseRegistry` from all response sources.

    The single source of truth for response merging — used at model load after
    project validation passes. Validation parses project ``responses.yml`` via
    :func:`~rasa.mantle.content.validation.load_project_responses_for_validation`.

    Loading order (later sources override earlier ones):

    0. Packaged system default responses (``default_skills/default_responses.yml``).
    1. Default skill ``responses.yml`` files (bundled with the package).
    2. Per-skill ``responses.yml`` files under *snapshot_skills_root*.
    3. *top_level_path* (project-wide overrides).

    Args:
        snapshot_skills_root: The ``skills/`` directory to scan for per-skill
            ``responses.yml`` files (extracted snapshot or project source tree).
        top_level_path: The top-level ``responses.yml`` file, which may not
            exist.
    """
    registry = load_bundled_response_registry()

    # 2. Per-project-skill responses from snapshot
    if snapshot_skills_root.is_dir():
        for skill_dir in sorted(snapshot_skills_root.iterdir()):
            if not skill_dir.is_dir() or skill_dir.name.startswith("_"):
                continue
            skill_responses = skill_dir / RESPONSES_FILENAME
            if skill_responses.is_file():
                registry = ResponseRegistry.from_yaml(skill_responses).merge(registry)

    # 3. Top-level responses (project-wide overrides)
    if top_level_path.is_file():
        registry = ResponseRegistry.from_yaml(top_level_path).merge(registry)

    return registry


def _resolve_integration_section(
    project_root: Union[str, Path, None],
    key: str,
    expected_type: type,
    default: Any,
) -> Any:
    """Return one section of an ``integrations.yml``.

    Returns the ``key`` section of the first ``integrations.yml`` that parses to a
    mapping and whose section matches *expected_type*; otherwise *default*. Shared
    by the live model-group readers so they use the same file lookup.

    When *project_root* is given, that root is the *only* source — there is no
    fall-through to the current working directory. This matters at model load,
    where callers pass the packaged snapshot root explicitly: a missing or
    non-matching section (including YAML ``null``) must resolve to *default*, not
    silently pick up a different ``integrations.yml`` from the serving host's cwd
    (which would drive query embeddings that mismatch the train-time index). The
    cwd is used only when no root is given at all.
    """
    raw = _read_integrations_mapping(project_root)
    if raw is None:
        return default
    section = raw.get(key, default)
    if isinstance(section, expected_type):
        return section
    return default


def _read_integrations_mapping(
    project_root: Union[str, Path, None],
) -> Mapping[str, Any] | None:
    """Return the live ``integrations.yml`` mapping, or ``None`` when unusable."""
    root = Path(project_root) if project_root is not None else Path.cwd()
    integration_file = root / MANTLE_INTEGRATIONS_FILE
    if not integration_file.is_file():
        return None
    raw = read_yaml_file(integration_file, expand_env_vars=False)
    if not isinstance(raw, Mapping):
        return None
    return raw


def resolve_integration_llm_config(
    agent: AgentSpec,
    project_root: Union[str, Path, None],
) -> Mapping[str, Any]:
    """Resolve the orchestrator LLM from the packaged spec and live model groups.

    The group id and optional prompt budget come from ``agent.orchestrator``.
    Definitions are read from the live project ``integrations.yml``
    ``model_groups`` (not the model snapshot), then resolved through
    :func:`rasa.mantle.config.model_group_lookup.resolve_named_model_group`.
    A lookup failure propagates unchanged. ``max_prompt_tokens`` stays on the
    returned mapping.

    Raises:
        InvalidConfigException: When the live file still contains ``llm:``,
            when the named group cannot be resolved, or when credentials
            on the resolved group are invalid.
    """
    raw = _read_integrations_mapping(project_root)
    if raw is not None and "llm" in raw:
        raise InvalidConfigException(LEFTOVER_LLM_SECTION_MESSAGE)
    orchestrator = agent.orchestrator
    model_groups = resolve_integration_model_groups(project_root)
    orchestrator_model_group = resolve_named_model_group(
        orchestrator.model_group,
        model_groups,
        part=_ORCHESTRATOR_COMPONENT_NAME,
    )

    result = dict(orchestrator_model_group)
    try:
        validate_model_group_credentials([result])
    except ValidationError as error:
        raise InvalidConfigException(
            f"The orchestrator model group '{orchestrator.model_group}' in "
            f"'{MANTLE_INTEGRATIONS_FILE}' has invalid credentials: "
            f"{error.info or error}"
        ) from error
    if orchestrator.max_prompt_tokens is not None:
        result[MAX_PROMPT_TOKENS_CONFIG_KEY] = orchestrator.max_prompt_tokens
    return result


def resolve_integration_model_groups(
    project_root: Union[str, Path, None],
) -> list[dict[str, Any]]:
    """Load ``model_groups`` from the project ``integrations.yml``.

    Returns the raw list of model-group declarations (``{id, models: [...],
    router?}``) so it can be handed to
    :func:`rasa.shared.utils.llm.resolve_model_client_config` as its
    ``model_groups`` argument. Read from the project root / cwd (not the model
    snapshot), mirroring :func:`resolve_integration_llm_config`. Returns ``[]``
    when no ``model_groups`` section is present.
    """
    return cast(
        "list[dict[str, Any]]",
        _resolve_integration_section(project_root, "model_groups", list, []),
    )


def _read_agent_yaml_from_archive(extracted_dir: Path) -> Mapping[str, Any] | None:
    """Read packaged agent identity from ``mantle_snapshot/agent.yml``.

    Archives that only contain the pre-M0.1 ``config.yml`` artifact are rejected.
    """
    if (extracted_dir / V2_AGENT_ARTIFACT_PATH).is_file():
        return _read_yaml_from_dir(extracted_dir, V2_AGENT_ARTIFACT_PATH)

    return None


def _read_yaml_from_dir(
    extracted_dir: Path,
    relative_path: str,
) -> Mapping[str, Any] | None:
    """Read a YAML file from an already-extracted archive directory."""
    payload_path = extracted_dir / relative_path
    if not payload_path.is_file():
        return None

    parsed_yaml = read_yaml_file(payload_path, expand_env_vars=False)
    if parsed_yaml is None:
        return None

    if not isinstance(parsed_yaml, Mapping):
        raise ValidationError(
            code="config.project_structure.invalid_generated_metadata",
            event_info=(
                "Mantle model metadata must be a mapping when loaded "
                "from the model archive."
            ),
        )

    return cast(Mapping[str, Any], parsed_yaml)
